import os from 'os';
import ctx from 'ctx';
import core from 'state-core';
import CodeMirror from 'codemirror';

async function refresh({ after }) {
  const v = 'extension.views.state-view', view = os.get(v), d = view['ui-data'];
  const R = os.refs['state-view'], cm = R.cm, H = os.history.commits;
  // Typing that local.edit has not picked up yet: leave the editor alone.
  if (R.shownEditable && cm.getValue() !== (R.draft === null ? R.base : R.draft)) return;
  const head = H[H.length - 1], atDraft = R.draft !== null && d.position === H.length;
  d.current_state_version = head.n;
  d.version = atDraft ? 'draft' : 'v' + H[d.position].n;
  d.version_ago = atDraft ? '' : core.ago(H[d.position].at);
  const editable = !d.changes && (atDraft || (R.draft === null && d.position === H.length - 1));

  // What the editor shows: the changes in a version, the draft, the live state (newest version), or an older version.
  let text, marks = [], edits = null;
  if (d.changes) {
    const p = core.pairAt(d.position, H, R.draft), cv = core.changesView(core.stripRuntime(p.before), core.stripRuntime(p.after));
    text = cv.text;
    marks = cv.marks;
  } else if (atDraft) {
    text = R.draft;
  } else if (editable) {
    // The newest version follows the live state; comments and layout stay, only changed values are rewritten.
    const p = core.patchText(R.base, os.get());
    text = p.text;
    if (JSON.stringify(core.parseJsonc(text)) !== JSON.stringify(os.get())) text = JSON.stringify(os.get(), null, 2);
    else if (cm.getValue() === R.base) edits = p.edits;
    R.base = text;
  } else {
    text = H[d.position].state;
  }

  R.setting = true;
  if (cm.getValue() !== text) {
    if (edits) cm.operation(() => edits.forEach(x => cm.replaceRange(x.insert, cm.posFromIndex(x.from), cm.posFromIndex(x.to))));
    if (cm.getValue() !== text) { cm.setValue(text); cm.clearHistory(); }
  }
  R.setting = false;
  R.shownEditable = editable;
  cm.setOption('readOnly', editable ? false : 'nocursor');
  cm.getWrapperElement().classList.toggle('CodeMirror-readonly', !editable);

  // Changes: added green, updated yellow (with the old value), deleted red.
  R.lines.forEach(l => cm.removeLineClass(l.h, 'background', l.cls));
  R.lines = [];
  R.widgets.forEach(w => w.clear());
  R.widgets = [];
  marks.forEach(m => {
    for (let l = m.from; l <= m.to; l++) R.lines.push({ h: cm.addLineClass(l, 'background', 'chg-' + m.type), cls: 'chg-' + m.type });
    if (m.type === 'updated') {
      const w = document.createElement('span');
      w.className = 'was';
      w.textContent = 'was ' + JSON.stringify(m.before);
      R.widgets.push(cm.setBookmark(CodeMirror.Pos(m.to, cm.getLine(m.to).length), { widget: w }));
    }
  });
  if (R.bad !== null) { cm.removeLineClass(R.bad, 'background', 'bad-line'); R.bad = null; }
  const at = /line (\d+)/.exec(d.error) || /position (\d+)/.exec(d.error);
  if (d.error && at) {
    R.bad = /line/.test(at[0]) ? +at[1] - 1 : cm.posFromIndex(+at[1]).line;
    cm.addLineClass(R.bad, 'background', 'bad-line');
  }

  // Long strings, and strings of more than one line, show as "...". A click opens the text in the viewer;
  // the pointer on it shows its start.
  R.long.forEach(m => m.clear());
  R.long = [];
  let spans = {};
  try { spans = core.spans(text); } catch (e) {}
  if (!R.tip) {
    R.tip = document.createElement('pre');
    R.tip.className = 'long-tip';
    R.tip.hidden = true;
    document.body.appendChild(R.tip);
  }
  Object.keys(spans).forEach(k => {
    const r = spans[k], p = JSON.parse(k).join('/');
    if (r.obj || text[r.start] !== '"' || (r.end - r.start < 90 && !text.slice(r.start, r.end).includes('\\n'))) return;
    const w = document.createElement('span');
    w.className = 'long';
    w.textContent = '"..."';
    w.title = p;
    w.addEventListener('mouseenter', () => {
      let value = '';
      try { value = JSON.parse(text.slice(r.start, r.end)); } catch (e) {}
      const lines = value.split('\n');
      R.tip.textContent = lines.slice(0, 14).join('\n').slice(0, 1200) + (lines.length > 14 ? '\n…' : '');
      R.tip.hidden = false;
      const b = w.getBoundingClientRect(), t = R.tip.getBoundingClientRect();
      R.tip.style.left = Math.max(8, Math.min(b.left, innerWidth - t.width - 8)) + 'px';
      R.tip.style.top = (b.bottom + 6 + t.height < innerHeight ? b.bottom + 6 : Math.max(8, b.top - 6 - t.height)) + 'px';
    });
    w.addEventListener('mouseleave', () => { R.tip.hidden = true; });
    w.addEventListener('mousedown', e => {
      e.preventDefault();
      R.tip.hidden = true;
      os.call('local.open-viewer', { path: p }, v).catch(console.error);
    });
    R.long.push(cm.markText(cm.posFromIndex(r.start), cm.posFromIndex(r.end), { replacedWith: w, atomic: true }));
  });

  // The bar is drawn again from ui-data; the viewer opens and closes with ui-data.viewer_path.
  const tmp = document.createElement('div');
  tmp.innerHTML = os.template(view.html, d);
  const bar = tmp.querySelector('.sv-bar');
  ctx.root.querySelector('.sv-bar').replaceWith(bar);
  os.bind(bar, v);
  ctx.root.querySelector('#sv-viewer').hidden = !d.viewer_path;
  ctx.root.querySelector('#sv-viewer-path').textContent = d.viewer_path;
  // md files show in the theme that ui-data names; its button is pressed.
  const themes = ctx.root.querySelector('#md-themes');
  themes.hidden = !/\.md$/.test(d.viewer_path);
  themes.querySelectorAll('[data-md-theme]').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.mdTheme === d.md_theme)));
  ctx.root.querySelector('#sv-viewer-doc').dataset.mdTheme = d.md_theme;
}

